/* the chapter's loss model (dB/km, λ in µm): Rayleigh C/λ⁴ with C = 0.8, the UV and IR tail formulas with x = 0.06,
   and the old fiber's OH⁻ band at 1383 nm (0.84 dB/km above the low-water-peak level; a band a few tens of nm wide) */
const OF_ry=l=>0.8/Math.pow(l,4);
const OF_uv=l=>(154.2*0.06/(46.6*0.06+60))*1e-2*Math.exp(4.63/l);
const OF_ir=l=>7.81e11*Math.exp(-48.48/l);
const OF_oh=(l,c=1.383)=>0.84*Math.exp(-Math.pow((l-c)/0.013,2)/2);
const OF_tot=(l,old)=>OF_ry(l)+OF_uv(l)+OF_ir(l)+(old?OF_oh(l):0);
/* a curve of f(λ) over [l0,l1] µm mapped into a box (x0..x1, y for value v from vy) */
const OF_curve=(f,l0,l1,x0,x1,vy,n=160)=>{const p=[];for(let i=0;i<=n;i++){const l=l0+(l1-l0)*i/n;p.push([x0+(x1-x0)*i/n,vy(f(l))])}return p};
const OF_mWdB=db=>Math.pow(10,db/10);

